    findings=[]
    lines=text.splitlines()
    for i,line in enumerate(lines):
        if re.match(r'^\s*on:\s*.*pull_request_target', line):
            c=line.find('pull_request_target')
            findings.append(_finding("dangerous-triggers","use of fundamentally insecure workflow trigger","High","Medium",path,
                "pull_request_target trigger", ["on"], i+1,c,c+len("pull_request_target"),"pull_request_target",source=text))
        m=re.match(r'^(\s*)-\s+uses:\s*["\']?([^\s"\']+)',line)
        if m:
            ref=m.group(2); indent=m.group(1); col=m.start(2)
            # A full 40-character SHA is pinned; local/docker references are not remote actions.
            if "@" in ref and not re.search(r'@[0-9a-fA-F]{40}$',ref):
                findings.append(_finding("unpinned-uses","unpinned action reference","High","High",path,
                  "action is not pinned to a hash (required by blanket policy)", ["jobs", _job(lines,i), "steps", _step_index(lines,i), "uses"], i+1,col,col+len(ref),ref,source=text))
            if ref.startswith("actions/checkout@"):
